<form method="GET" action="{{ $filterAction??route('search-jobs') }}"><label for="filter-keyword"><span>Keywords</span><input id="filter-keyword" name="title" type="search" maxlength="120" value="{{ $title }}" placeholder="Job title, keyword or company"></label><label for="filter-country"><span>Location</span><select id="filter-country" name="country_id"><option value="">All locations</option>@foreach($locations as $location)<option value="{{ $location->id }}" @selected((string)$country_id === (string)$location->id)>{{ $location->name }}</option>@endforeach</select></label><label for="filter-category"><span>Category</span><select id="filter-category" name="category_id"><option value="">All categories</option>@foreach($job_categories as $category)<option value="{{ $category->id }}" @selected((string)$category_id === (string)$category->id)>{{ $category->name }}</option>@endforeach</select></label><label for="filter-period"><span>Salary period</span><select id="filter-period" name="salary_type"><option value="">All periods</option>@foreach(['hourly','daily','weekly','monthly','yearly'] as $period)<option value="{{ $period }}" @selected(request('salary_type') === $period)>{{ ucfirst($period) }}</option>@endforeach</select></label><div class="jg-filter-actions"><button class="jg-button">Apply Filters</button><a href="{{ $filterAction??route('search-jobs') }}">Reset filters</a></div></form>